api.look('paper');
const cx=api.w/2, cy=330;
const k=api.seg(t,0,1.4);
api.circle(cx,cy,130,{c:'accent',w:5,k,fill:'accent',a:0.12});
api.path('M-90 20 C-70 -60 -20 -80 0 -30 C20 -80 70 -60 90 20 C60 0 30 10 0 60 C-30 10 -60 0 -90 20 Z',{x:cx,y:cy,s:1.3,c:'accent',w:5,fill:'accent',k});
api.kinetic('ROME',cx,cy+210,{mode:'pop',k:api.seg(t,1,2.2),size:56,t});
api.say('Rome began as one city',0.3,3.3);

api.look('paper');
const cx=api.w/2;
const pts=[['27 BC',0,'Augustus'],['117 AD',1,'Trajan']];
api.text('The Empire grows',cx,70,{size:34,weight:'bold',align:'center',k:api.seg(t,0,1)});
const k=api.ease(api.seg(t,0.3,4));
api.circle(cx,330,30+190*k,{c:'accent',w:5,fill:'accent',a:0.15});
api.circle(cx,330,30+120*k,{c:'a2',w:4,fill:'a2',a:0.15});
api.circle(cx,330,30,{c:'fg',w:4,fill:'fg',a:0.9});
api.shape('star',cx,330,36,{c:'ink',fill:'ink'});
api.callout('Rome, 27 BC',cx,330,90,200,{k:api.seg(t,0.8,1.8)});
api.callout('Gaul, Spain',cx-110,360,70,520,{k:api.seg(t,2,3)});
api.callout('Egypt, Syria',cx+120,320,300,520,{k:api.seg(t,3,4)});
api.counter(5000000,cx,640,{k:api.seg(t,0.5,4.5),suf:' km² at its peak',size:30});
api.say('Conquest made it huge',0.3,5.5);

api.look('paper');
const cx=api.w/2;
api.text('Peak: 117 AD',cx,70,{size:34,weight:'bold',align:'center'});
api.bars([{label:'27 BC',v:2,c:'a2'},{label:'14 AD',v:3.5,c:'a2'},{label:'117 AD',v:5,c:'accent'}],50,170,api.w-100,380,{k:api.seg(t,0.3,3)});
api.scribble(cx+100,200,70,40,{k:api.seg(t,3,4)});
api.text('millions of km²',cx,590,{size:20,align:'center',k:api.seg(t,2,3)});
api.say('Then it stopped growing',0.3,4.5);

api.look('paper');
const cx=api.w/2, cy=330;
api.text('The cracks',cx,70,{size:34,weight:'bold',align:'center'});
const sh=api.shake(t,api.seg(t,2,5)*3);
const items=[['Plague',-95,-60],['Rebels',95,-60],['Debt',-95,70],['Invaders',95,70]];
api.circle(cx,cy,60,{c:'fg',w:4,fill:'accent',a:0.3});
api.shape('star',cx,cy,40,{c:'fg'});
items.forEach((it,i)=>{
 const k=api.stag(t,i,{gap:0.8,dur:0.8,from:0.5});
 api.arrow(cx+it[1]*2,cy+it[2]*2.2,cx+it[1]*0.6,cy+it[2]*0.6,{c:'bad',w:4,k});
 api.label(it[0],cx+it[1]*2,cy+it[2]*2.2,{k});
});
api.path('M-10 -50 L5 -20 L-8 0 L8 30 L-2 55',{x:cx,y:cy,s:1,c:'bad',w:4,k:api.seg(t,3,5)});
api.say('Pressure came from everywhere',0.3,5.5);

api.look('paper');
const cx=api.w/2;
api.text('Split in two',cx,70,{size:34,weight:'bold',align:'center'});
const k=api.ease(api.seg(t,0.4,2.4));
const gap=k*60;
api.circle(cx-gap-70,330,110,{c:'accent',w:5,fill:'accent',a:0.2});
api.circle(cx+gap+70,330,110,{c:'a3',w:5,fill:'a3',a:0.2});
api.text('West',cx-gap-70,330,{size:26,align:'center',weight:'bold'});
api.text('East',cx+gap+70,330,{size:26,align:'center',weight:'bold'});
api.text('Rome',cx-gap-70,470,{size:20,align:'center',c:'accent',k:api.seg(t,2.4,3)});
api.text('Constantinople',cx+gap+70,470,{size:18,align:'center',c:'a3',k:api.seg(t,2.4,3)});
api.say('East and West drifted apart',0.3,4.5);

api.look('paper');
const cx=api.w/2;
api.text('476 AD',cx,90,{size:44,weight:'bold',align:'center',c:'bad'});
const k=api.seg(t,0.5,3.5);
api.circle(cx,330,150*(1-k*0.9)+10,{c:'accent',w:5,fill:'accent',a:0.2*(1-k)});
api.swarm(60,t,{mode:'burst',cx,cy:330,rx:150,ry:150,c:'accent',k:api.seg(t,0.5,4)});
api.text('Last emperor removed',cx,560,{size:22,align:'center',k:api.seg(t,3,4)});
api.text('East lived on to 1453',cx,600,{size:20,align:'center',c:'a3',k:api.seg(t,4,5)});
api.say('The West fell in 476',0.3,5.5);
